<?php $ticketRows=$tickets??$list; ?>
<div class="table-wrap"><table><thead><tr><th>Mã yêu cầu</th><th>Nội dung</th><th>Ưu tiên</th><th>Trạng thái</th><th>Cập nhật</th></tr></thead><tbody><?php foreach($ticketRows as $row): ?><tr><td><a class="ticket-id" href="/tickets/view?id=<?= e($row['id']) ?>">#<?= e(str_pad((string)$row['id'],4,'0',STR_PAD_LEFT)) ?></a></td><td><a href="/tickets/view?id=<?= e($row['id']) ?>"><?= e($row['tieu_de']) ?></a><?php if(isset($row['ho_ten'])): ?><small class="cell-subtitle"><?= e($row['ho_ten']) ?></small><?php endif ?></td><td><?php badge($row['uu_tien']) ?></td><td><?php badge($row['trang_thai']) ?></td><td class="muted"><?= e(date('d/m/Y H:i',strtotime($row['ngay_cap_nhat']))) ?></td></tr><?php endforeach ?><?php if(!$ticketRows): ?><tr><td colspan="5" class="empty">Chưa có yêu cầu hỗ trợ.</td></tr><?php endif ?></tbody></table></div>
